    1	//! Live round trip of a thought signature. Ignored by default.
    2	//!
    3	//! Run: `GEMINI_API_KEY=... cargo test -p paigasus-helikon-providers-gemini -- --ignored live`
    4	//! Optional: `GEMINI_MODEL_ID` (default `gemini-3.8-flash`).
    5	
    6	use futures_util::StreamExt;
    7	use paigasus_helikon_core::{
    8	    CancellationToken, ContentPart, Item, Model, ModelEvent, ModelRequest, ModelTurnAccumulator,
    9	    ToolChoice, ToolDef,
   10	};
   11	
   12	use crate::translate::build_request;
   13	use crate::{GeminiModel, PROVIDER_DATA_KEY};
   14	
   15	fn search_tool() -> ToolDef {
   16	    ToolDef {
   17	        name: "search".into(),
   18	        description: "Search for a query.".into(),
   19	        schema: serde_json::json!({
   20	            "type":"object","properties":{"q":{"type":"string"}},"required":["q"]
   21	        }),
   22	    }
   23	}
   24	
   25	#[tokio::test]
   26	#[ignore]
   27	async fn live_signature_round_trip() {
   28	    if std::env::var("GEMINI_API_KEY").is_err() && std::env::var("GOOGLE_API_KEY").is_err() {
   29	        eprintln!("skipped: set GEMINI_API_KEY or GOOGLE_API_KEY");
   30	        return;
   31	    }
   32	    let id = std::env::var("GEMINI_MODEL_ID").unwrap_or_else(|_| "gemini-3.8-flash".into());
   33	    let model = GeminiModel::from_env(id).unwrap();
   34	
   35	    let mut request = ModelRequest::new();
   36	    request.messages = vec![Item::UserMessage {
   37	        content: vec![ContentPart::Text {
   38	            text: "Use the search tool to look up cats. Do not answer before you search.".into(),
   39	        }],
   40	    }];
   41	    request.tools = vec![search_tool()];
   42	    // Turn 1 must call the tool. Turn 2 must not be forced.
   43	    request.model_settings.tool_choice = Some(ToolChoice::Tool {
   44	        name: "search".into(),
   45	    });
   46	
   47	    // Turn 1: collect the turn and look for a signed call.
   48	    let mut stream = model
   49	        .invoke(request.clone(), CancellationToken::new())
   50	        .await
   51	        .unwrap();
   52	    let mut acc = ModelTurnAccumulator::new("root");
   53	    while let Some(ev) = stream.next().await {
   54	        acc.observe(&ev.expect("turn 1 stream error"));
   55	    }
   56	    let items = acc.finish().unwrap().items;
   57	
   58	    let signature = items
   59	        .iter()
   60	        .find_map(|item| {
   61	            let Item::AssistantMessage { content, .. } = item else {
   62	                return None;
   63	            };
   64	            content.iter().find_map(|part| match part {
   65	                ContentPart::ProviderData {
   66	                    provider,
   67	                    call_id: Some(_),
   68	                    data,
   69	                } if provider == PROVIDER_DATA_KEY => data
   70	                    .get("thoughtSignature")
   71	                    .and_then(|s| s.as_str())
   72	                    .filter(|s| !s.is_empty())
   73	                    .map(str::to_owned),
   74	                _ => None,
   75	            })
   76	        })
   77	        .expect("turn 1 has a gemini ProviderData with a thoughtSignature and a call id");
   78	
   79	    // Turn 2 request: the turn, then one result per call, and no user text.
   80	    let mut messages = request.messages.clone();
   81	    messages.extend(items.iter().cloned());
   82	    for item in &items {
   83	        if let Item::ToolCall { call_id, .. } = item {
   84	            messages.push(Item::ToolResult {
   85	                call_id: call_id.clone(),
   86	                content: vec![ContentPart::Text {
   87	                    text: r#"{"hits":3}"#.into(),
   88	                }],
   89	            });
   90	        }
   91	    }
   92	    request.messages = messages;
   93	    request.model_settings.tool_choice = None;
   94	
   95	    let body = build_request(&model.0, &request).unwrap().body;
   96	    let signatures: Vec<&serde_json::Value> = body["contents"]
   97	        .as_array()
   98	        .expect("contents array")
   99	        .iter()
  100	        .flat_map(|c| c["parts"].as_array().into_iter().flatten())
  101	        .filter(|p| p.get("functionCall").is_some())
  102	        .map(|p| &p["thoughtSignature"])
  103	        .collect();
  104	    assert!(
  105	        signatures.iter().any(|s| s.as_str() == Some(&signature)),
  106	        "no functionCall part carries the captured signature: {body}"
  107	    );
  108	    assert!(
  109	        !body
  110	            .to_string()
  111	            .contains(crate::translate::request::DUMMY_THOUGHT_SIGNATURE),
  112	        "a dummy signature is in the request"
  113	    );
  114	
  115	    let mut stream = model
  116	        .invoke(request, CancellationToken::new())
  117	        .await
  118	        .unwrap();
  119	    let mut finished = false;
  120	    while let Some(ev) = stream.next().await {
  121	        if let ModelEvent::Finish { .. } = ev.expect("turn 2 stream error") {
  122	            finished = true;
  123	        }
  124	    }
  125	    assert!(finished, "turn 2 has no Finish event");
  126	}
